llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "In healthy male volunteers, oral naltrexone had an oral bioavailability of about 5%, attributed to extensive first-pass hepatic metabolism; naltrexone shares the 6-keto, 14-hydroxy, 4,5-epoxy morphinan core with the query, supporting low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Absolute oral bioavailability of naltrexone was reported as 5% in healthy and post-addict volunteers, providing direct low-F evidence for a close structural analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "M6G is reported to have poor oral bioavailability in humans, requiring intravenous administration; although a glucuronide, it is a morphinan with low oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "ThH, a related morphinan, has very low oral bioavailability in humans after tablet administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Morphine has an absolute oral bioavailability of 29.2% in healthy volunteers, showing that N-methyl morphinans can exceed 20% when lacking the 6-keto/14-hydroxy motif.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene has an absolute oral bioavailability of 41% in humans, indicating that some 14-hydroxy morphinans can have high oral F, but it differs at the N-substituent and 6-methylene position.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Samidorphan has an absolute oral bioavailability of 68.6% in healthy participants, another high-F morphinan, though with lower structural similarity to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction is low: the closest high-similarity analogue naltrexone has consistently low oral bioavailability (about 5-10%) due to first-pass metabolism, and the query shares the 6-keto/14-hydroxy morphinan core. High-F analogues differ at key positions (N-substituent, 6-methylene, or additional polar groups) and are less transferable, so F < 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the supplied evidence.",
    "Naltrexone records are mixed (5-60%), and some high-F analogues have lower structural similarity, leaving uncertainty in the magnitude of first-pass metabolism for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

